-- Gerado por ferramentas/docx_para_sql.py — etapa 2, parte 6 de 8
-- Pode ser executado mais de uma vez; as partes podem ser executadas em qualquer ordem.
begin;
do $$ begin if (select count(*) from encontros where etapa_id=(select id from etapas where numero=2)) <> 35 then raise exception 'A etapa 2 não tem 35 encontros no banco — a atualização por ordem não é segura.'; end if; end $$;
update encontros set conteudo_html='<p><strong>Palavra inicial:</strong> No encontro de hoje, onde encerramos toda uma reflexão sobre a fé que professamos, queremos não mais ver apenas partes, mas olhar para todo o conjunto da oração. Queremos ver o que os catequizandos assimilaram sobre tudo o que foi falado no decorrer do ano.</p> <p><strong>Preparar o ambiente:</strong> Ambão com toalha da cor do Tempo Litúrgico, vela, flores. Cartaz contendo os 12 artigos da Profissão de Fé.</p> <p><strong>Acolhida:</strong> O catequista acolhe carinhosamente os catequizandos com a frase: "Professai a cada dia a fé... N..., seja bem-vindo!", e os conduz para a sala de encontro.</p> <p><strong>Recordação da vida:</strong> Ao redor da Mesa da Partilha ou da Mesa da Palavra o catequista motiva os catequizandos a fazer um momento de recordação da vida, onde lembrarão fatos e acontecimentos que marcaram a vida de cada um, de suas famílias, comunidade e da sociedade.</p> <h4>Na Mesa da Palavra</h4> <p><strong>Oração inicial:</strong> Após o momento de recordação da vida, o catequista inicia um momento de oração pedindo o Espírito Santo sobre todos os catequizandos e sobre toda a Igreja.</p> <p>O catequizando (escalado como leitor do encontro) dirige-se até o ambão, de onde proclama o texto bíblico.</p> <p><strong>Leitura do texto bíblico:</strong> At 2,22-24.32-33.36.</p> <p>Depois de um momento de silêncio o catequista lê o texto novamente bem devagar, destacando alguns pontos.</p> <p>"Israelitas, escutai estas palavras [...] Todos de Israel saibam, portanto, com a maior certeza, que este Jesus, por vós crucificado, Deus o constituiu Senhor e Cristo."</p> <p>Todos se dirigem para a Mesa da Partilha.</p> <h4>Na Mesa da Partilha</h4> <p>O catequista incentiva os catequizandos a reconstruírem o texto bíblico. Deixar que falem. Depois pedir aos catequizandos para abrir suas bíblias na passagem proclamada na Mesa da Palavra, e os convida a uma leitura silenciosa observando algum detalhe não comentado na reconstrução do texto. Se houver algo, todos podem partilhar.</p> <p>O catequista poderá perguntar aos catequizandos o que é professar a fé e como eles podem fazer isso no dia a dia. Deixar os catequizandos falarem.</p> <p>Depois mostra-lhes o cartaz com os doze artigos do Credo e pede para que leiam todos juntos artigo por artigo e, à medida que forem lendo, o catequista os estimula a recapitularem tudo o que aprenderam ao longo do ano, o que lembram e sabem sobre cada artigo. No final, o catequista poderá pedir para que os catequizandos resumam numa frase o que é crer e o que é a fé no Cristo. Essas frases poderão ser reunidas em uma cartolina e afixada na Mesa da Palavra.</p> <p>Fazer esse momento de recordação de todo conteúdo refletido no decorrer do ano com muita calma, deixando realmente os catequizandos participarem. Depois poderá ser rezado o Credo todo e ao final cantar um canto.</p> <p><strong>Conclusão:</strong> O catequista convida a cada catequizando a ficar alguns minutos em silêncio e formular um gesto concreto, uma atitude para que possa, como os discípulos, anunciar e testemunhar a fé. É um compromisso pessoal e cada um deverá formular e assumir o seu pelo tempo que cada um achar necessário.</p> <p>Explicar que no próximo encontro será preparada a celebração onde todos eles irão "professar a fé", através da recitação do Credo, diante de toda a comunidade. Explicar a importância desse ato.</p> <p><strong>Oração final:</strong> O catequista convida a todos a se colocarem ao redor da Mesa da Palavra onde estimula os catequizandos a formularem preces e orações principalmente por todos que estão abraçando a fé e estão espalhados pelo mundo. Conclui com o Pai-nosso e com a oração:</p> <p>"Deus Pai criador, que conhece o coração de cada um de nós, ajudai-nos a testemunhar a fé e a vivê-la a cada dia. Que nosso testemunho e exemplo seja sinal para esse mundo sem esperança e cheio de guerra. Por Cristo Nosso Senhor. Amém"</p> <p>No final da oração, o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte, dizendo:</p> <p>“...N... professai a fé com a vida, vai em paz, e que o Senhor te acompanhe!”</p>', preparo_html='<p>Ambão com toalha da cor do Tempo Litúrgico, vela, flores. Cartaz contendo os 12 artigos da Profissão de Fé.</p>', atualizado_em=now() where etapa_id=(select id from etapas where numero=2) and ordem=32; -- A Profissão de Fé
update encontros set conteudo_html='<p><strong>Palavra inicial:</strong> Caríssimo catequista, estamos encerrando a segunda etapa da catequese. Nesse encontro queremos preparar os catequizandos para a celebração de Recitação da Profissão de Fé. Seria importante já ter lido o roteiro celebrativo e ter em mente todo o desenrolar da celebração.</p> <p><strong>Preparando o ambiente:</strong> Ambão com toalha verde, Bíblia, vela e flores. Na Mesa da Partilha, folha com a “Profissão de Fé” que os catequizandos receberam no início da segunda etapa.</p> <p><strong>Acolhida:</strong> O catequista acolhe os catequizandos traçando-lhes o sinal da cruz em sua fronte e dizendo: “...N..., Jesus hoje te pergunta: Você crê em mim? Seja bom discípulo e testemunha de Cristo!”</p> <p><strong>Recordação da vida:</strong> Quando todos estiverem ao redor da Mesa da Partilha ou da Mesa da Palavra, o catequista os incentiva a trazer presente fatos e acontecimentos que marcaram a semana.</p> <h4>Na Mesa da Palavra</h4> <p><strong>Oração inicial:</strong> O catequista invoca o Espírito Santo com uma oração ou canto à escolha. Logo convida a todos a aclamarem o Evangelho e em seguida dirige-se à Mesa da Palavra e proclama o texto indicado.</p> <p><strong>Leitura do texto bíblico:</strong> Mt 25,31-40.</p> <p>O próprio catequista lê o texto indicado e em seguida lê novamente, desta vez pausadamente, destacando alguns pontos do texto:</p> <p>“[...] Tomai posse do Reino preparado para vós desde a criação do mundo. [...] todas as vezes que vocês fizestes isso a um desses meus irmãos menores, a mim o fizestes”.</p> <p>Após a leitura todos dirigem-se para a Mesa da Partilha.</p> <h4>Na Mesa da Partilha</h4> <p>Reconstruir o texto junto aos catequizandos dizendo que professar a fé é reconhecer Cristo como Rei do Universo e colocar em prática os seus mandamentos, principalmente com os mais pobres e pequeninos deste mundo.</p> <p>O catequista deverá também explicar um pouco a liturgia da Solenidade de Nosso Senhor Jesus Cristo, Rei do Universo, se a celebração acontecer neste dia. Por motivos pastorais a celebração pode ocorrer num outro dia.</p> <p>Explicar passo a passo aos catequizandos a celebração de Recitação da Profissão de Fé, bem como sua importância e seu significado.</p> <p>Na celebração de Recitação da Profissão de Fé vamos ser convidados a dar o nosso sim, mais uma vez, a Jesus, testemunhando e professando a nossa fé perante a comunidade, mostrando o caminho de amadurecimento na fé que temos percorrido.</p> <p>Poderá também fazer um rápido ensaio: procissão de entrada, onde vão sentar, o que vão responder, mostrar a folha com o Credo que já receberam e o qual agora professarão publicamente.</p> <p>Ainda poderá realizar ou marcar um ensaio para os cantos.</p> <p>Lembrar que o encontro da próxima semana é uma reunião com os pais e padrinhos de Batismo. Nesta reunião deverá ser refletido sobre a importância e significado da celebração. Explicar passo a passo o desenrolar dos ritos e distribuir algumas funções como veremos nas orientações do próximo encontro (a reunião com os pais e padrinhos poderá ser agendada em dia e horário que facilite a participação de todos, principalmente dos que trabalham e moram longe).</p> <p><strong>Conclusão:</strong> No decorrer da semana lembrar os pais e padrinhos de Batismo da reunião da próxima semana, comparecer aos ensaios e convidar os amigos e parentes para participarem da celebração.</p> <p><strong>Oração final:</strong> Ao redor da Mesa da Palavra de mãos dadas rezar o Pai-nosso. O catequista conclui com a oração:</p> <p>"Deus, Pai de bondade, concedei-nos a graça de testemunhar e professar a fé até o final de nossos dias. Que saibamos reconhecê-lo nos pobres e pequenos. Por Cristo Nosso Senhor. Amém."</p> <p>No final da oração o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte, dizendo:</p> <p>"...N... testemunhe o Cristo, vai em paz, e que o Senhor te acompanhe! Amém."</p>', preparo_html='<p>Ambão com toalha verde, Bíblia, vela e flores. Na Mesa da Partilha, folha com a “Profissão de Fé” que os catequizandos receberam no início da segunda etapa.</p>', atualizado_em=now() where etapa_id=(select id from etapas where numero=2) and ordem=33; -- Preparando a celebração de “Recitação da Profissão de Fé”
update encontros set conteudo_html='<p>Com os pais e padrinhos de Batismo</p> <p><em>(Encontro a ser realizado na semana que antecede a celebração de Recitação da Profissão de Fé)</em></p> <p><strong>Palavra inicial:</strong> Prezados catequistas, nesta reunião queremos apresentar aos pais e padrinhos de Batismo uma visão geral de como será a celebração de Recitação da Profissão de Fé. Primeiramente uma reflexão sobre a importância e significado, e depois o desenrolar dos ritos.</p> <p><strong>Preparando o ambiente:</strong> O espaço para a reunião poderá ser outra sala, mais ampla para acomodar todos os participantes. Nesta sala providenciar: ambão com toalha verde, Bíblia, vela e flores. Folhas com o roteiro da celebração.</p> <p><strong>Acolhida:</strong> O catequista acolhe os pais e padrinhos, dando-lhes boas-vindas e explicando o motivo da reunião. Logo após convida a todos a ficarem de pé e fazerem uma breve oração (se o tempo permitir poderá ser feita a “leitura orante” de um texto bíblico que poderá ser o mesmo usado na preparação dos catequizandos, do encontro 30).</p> <p><strong>Oração inicial:</strong> Pode-se invocar o Espírito Santo com a oração “Vinde, Espírito Santo, enchei...”, e fazer a leitura de um texto bíblico.</p> <p><strong>Orientações para a reunião:</strong></p> <ul> <li><p>Primeiramente agradecer a presença dos pais e padrinhos e pedir para que se apresentem e digam se são pais ou padrinhos.</p></li> <li><p>Introduzir com uma breve explicação sobre o Tempo Litúrgico, principalmente o significado da solenidade de “Cristo Rei” (se a celebração acontecer nessa data).</p></li> <li><p>O catequista faz uma breve reflexão sobre a importância e significado da celebração.</p></li> <li><p>Depois distribui o roteiro da celebração e explica passo a passo todo o desenrolar dos ritos.</p></li> <li><p>Orientá-los da importância de se rezar em família e de incentivar a leitura bíblica com os filhos.</p></li> <li><p>Poderá distribuir algumas funções como leitores dos textos bíblicos, oração da assembleia, apresentação das oferendas.</p></li> <li><p>Orientar para que as fotos e filmagens sejam discretas e não atrapalhem a participação da assembleia.</p></li> <li><p>Hora e local, chegar com antecedência.</p></li> </ul> <p><strong>Oração final:</strong> O catequista convida a todos a rezar o Pai-nosso e logo depois de braços abertos conclui com a oração:</p> <p>"Deus Pai criador, fazei que estes pais e padrinhos possam ajudar seus filhos e afilhados a professarem a fé a cada dia no Cristo e na Igreja, através do seu exemplo e testemunho. Que eles sejam amparados com sua força e iluminados por teu Espírito na orientação daqueles que lhes foram confiados. Por Cristo Nosso Senhor. Amém."</p> <p>"Ide em paz, e que o Senhor vos acompanhe!"</p>', preparo_html='<p>O espaço para a reunião poderá ser outra sala, mais ampla para acomodar todos os participantes. Nesta sala providenciar: ambão com toalha verde, Bíblia, vela e flores. Folhas com o roteiro da celebração.</p>', atualizado_em=now() where etapa_id=(select id from etapas where numero=2) and ordem=34; -- Preparando a celebração de “Recitação da Profissão de Fé”
update encontros set conteudo_html='<p><em>(Aconselhamos que essa celebração aconteça na Solenidade de Nosso Senhor Jesus Cristo, Rei do Universo. Porém, por motivos pastorais, pode ocorrer num outro dia)</em></p> <p><strong>Palavra inicial:</strong> Esta celebração tem o objetivo de apresentar a toda a comunidade os catequizandos que concluíram a segunda etapa da catequese, chamando a atenção para a grandeza de importância desse processo para a vida da Igreja, bem como assistir os catequizandos que recitarão publicamente a "Profissão de Fé".</p> <p><strong>Preparando o ambiente:</strong> Livro dos catequizandos onde foi registrado os nomes dos catequizandos ao final da primeira etapa. Reservar bancos para os catequizandos e padrinhos.</p> <p><strong>Procissão inicial:</strong> Os catequizandos e padrinhos de batismo participam da procissão inicial. Pode-se levar ainda a imagem de Cristo Rei, livro grande com os nomes dos catequizandos.</p> <p><strong>Saudação inicial:</strong> O presidente acolhe os catequizandos, familiares e padrinhos.</p> <p><em>(tudo segue como de costume, até depois da homilia)</em></p> <h4>Rita do "Éfeta" e Recitação do Símbolo³</h4> <p><em>(Após a proclamação do Evangelho e a homilia o diácono, ou, na falta dele, o catequista, pega o livro solenemente com os nomes dos catequizandos e chama-os cada um pelo nome.)</em></p> <p><strong>Diácono:</strong> Queiram aproximar-se os que estão com os nomes inscritos no livro dos catequizandos e que Recitarão o Símbolo: ...N..., ...N... <em>(lê-se do livro os nomes – se forem muitos pode-se omitir a leitura dos nomes)</em></p> <p><strong>Cada um responde individualmente:</strong> Presente! <em>(ou todos juntos se forem muitos)</em></p> <p><strong>Presidente:</strong> Queridos catequizandos, queiram aproximar-se para recitar as palavras de fé que lhes foram entregues e vocês desejam guardar com pureza de coração. Elas são o símbolo, isto é, um resumo de nossa fé. São poucas, mas contêm grandes mistérios.</p> <p><em>(Quem preside convida à oração, dizendo:)</em></p> <p><strong>Presidente:</strong> Oremos, irmãos e irmãs, para que Deus conserve e faça crescer sempre a fé que foi semeada no coração destes eleitos.</p> <p><em>(Depois de um tempo de silêncio, prossegue:)</em></p> <p><strong>Presidente:</strong> Concedei, Senhor, que estes catequizandos, tendo acolhido o vosso plano de amor e os mistérios da vida de vosso Cristo, possam sempre proclamá-lo com palavras e vivê-los pela fé, cumprindo em ações a vossa vontade. Por Cristo, Nosso Senhor.</p> <p><strong>Todos:</strong> Amém.</p> <p><em>(A seguir, quem preside prossegue com o rito do "Éfeta". Os catequizandos aproximam-se do presidente de cada vez e este, tocando com o polegar os ouvidos e os lábios de cada eleito, diz:)</em></p> <p><strong>Presidente:</strong> Éfeta, isto é, abre-te, a fim de proclamares o que ouviste, para louvor e glória de Deus.</p> <p>Se os catequizandos forem muitos, dir-se-á a fórmula inteira só para o primeiro; para os outros, apenas: Éfeta, isto é, abre-te. Ao final todos os catequizandos recitam o Símbolo e a missa prossegue com a "Oração da Assembleia".</p> <p><strong>Preces:</strong> Na "Oração da Assembleia" podem-se acrescentar algumas das orações:</p> <ul> <li><p>Para que esses catequizandos recebam o dom da fé, pela qual proclamem que Cristo é a ressurreição e a vida, roguemos ao Senhor.</p></li> </ul> <p>³ Adaptado do Ritual da Iniciação Cristã de Adultos – RICA.</p> <ul> <li><p>Para que, na esperança do Espírito vivificante, se disponham corajosamente a renovar sua vida, roguemos ao Senhor.</p></li> <li><p>Para que a família desses catequizandos e seus padrinhos coloquem sua esperança em Cristo e nele encontrem paz e santidade, roguemos ao Senhor.</p></li> <li><p>Para que toda nossa comunidade saiba acolher com alegria esses catequizandos e ajudá-los a viver a fé, roguemos ao Senhor.</p></li> <li><p>Para que todos nós, vivendo uma nova vida, manifestemos ao mundo o poder da ressurreição de Cristo, roguemos ao Senhor.</p></li> <li><p>Para que as famílias e os povos impedidos de abraçar a fé tenham a liberdade de crer no Evangelho, roguemos ao Senhor.</p></li> </ul> <p>A celebração prossegue como de costume até o seu final.</p>', preparo_html='<p>Livro dos catequizandos onde foi registrado os nomes dos catequizandos ao final da primeira etapa. Reservar bancos para os catequizandos e padrinhos.</p>', atualizado_em=now() where etapa_id=(select id from etapas where numero=2) and ordem=35; -- Celebração de Recitação da Profissão de Fé
delete from etapa_materiais where etapa_id=(select id from etapas where numero=2) and ordem=1; insert into etapa_materiais (etapa_id, titulo, conteudo_html, ordem) values ((select id from etapas where numero=2), 'Apresentação', '<p>Caríssimos Catequistas, paz!</p> <p>Após um trabalho dedicado da nossa equipe diocesana, é apresentado o segundo volume do método catequético de preparação para a Primeira Eucaristia da Diocese de Barretos. Esta segunda etapa tem uma importância capital no itinerário catequético: é a entrega aos catequizandos das verdades da nossa fé. Será todo um ano de vivência da "Traditio Symboli" (entrega do Símbolo da fé). As palavras da catequese de São Cirilo de Jerusalém devem servir de inspiração aos catequistas para o trabalho deste ano:</p> <p>"Abraça, cuidadoso, unicamente a fé que agora a Igreja te entrega para aprendê-la e confessá-la, protegida pelos muros da Escritura... para que não pereçam por ignorância, em nossos poucos versículos do símbolo todo dogma da fé. Exorto-te a tê-lo como viático durante a vida inteira e não admitir nenhum outro mais... Porque não foi à bel-prazer dos homens que este resumo da fé foi composto, mas selecionados dentre toda a Escritura. Os tópicos mais importantes perfazem e abraçam a única doutrina da fé. Da forma como a semente de mostarda num pequenino grão contém muitos ramos, assim este símbolo em poucas palavras encerra como num seio materno o conhecimento de toda a religião contida no Antigo e no Novo Testamento... Agora te foi dado o tesouro da vida."</p> <p>(S. Cirilo de Jerusalém, cat. 5 De fide et Symbolo 12-13, apud Liturgia das Horas, vol. IV p. 423-424. Vozes, Paulus, Paulinas, Ave-Maria, 1999)</p> <p>Quero dizer aos catequistas, especialmente em virtude da importância desta 2ª etapa, três atitudes que devem acompanhá-los durante o trabalho de evangelização dos catequizandos neste ano:</p> <p>1ª A SAGRADA ESCRITURA seja a sua companheira para que as verdades da fé que serão transmitidas estejam sempre iluminadas pela Palavra de Deus. Você, catequista, seja o(a) primeiro(a) a buscar nas Escrituras o seu alimento e energia, através da Leitura Orante pessoal, para a missão que Deus lhe está confiando através da Igreja.</p> <p>2ª O CATECISMO DA IGREJA CATÓLICA seja o item indispensável da sua biblioteca. Impossível preparar as catequeses desta 2ª etapa sem o Catecismo da Igreja Católica. É importante estar consciente que não entregarão aos catequizandos a sua fé, mas a da Igreja. É maior a exigência do estudo pessoal do(a) catequista nesta 2ª etapa.</p> <p>3ª A PARTICIPAÇÃO NA VIDA DA PARÓQUIA, embora seja um requisito para todo cristão, para o(a) catequista da 2ª etapa, é o testemunho de que a fé que ensina, crê e celebra é a mesma que vive no seu ser Igreja.</p> <p>A todos os catequistas, quero, enfim, desejar um bom trabalho e assegurar-lhes que lhes estou acompanhando com as minhas orações e minha bênção.</p> <p>† Edmilson Amador Caetano, O.Cist.<br/> Bispo Diocesano de Barretos<br/> Barretos, 4 de agosto de 2011.<br/> Festa de São João Maria Vianney, pároco e catequista.</p>', 1); -- material: Apresentação
delete from etapa_materiais where etapa_id=(select id from etapas where numero=2) and ordem=2; insert into etapa_materiais (etapa_id, titulo, conteudo_html, ordem) values ((select id from etapas where numero=2), 'Apresentação da Obra', '<p>O subsídio para a Pastoral Catequética da Diocese de Barretos, bem como toda a metodologia presente neste material, foi baseada na Palavra de Deus, na longínqua tradição da Igreja que nos foi transmitida, na análise de outros materiais que nos serviram de inspiração e na experiência de nossos catequistas.</p> <p>Ao preparar os subsídios para o catequista e, Diário Catequético e Espiritual do Catequizando nossa equipe considerou que a Igreja sempre teve um calendário próprio e diferente do calendário civil, chamado de "Calendário Litúrgico". Portanto, a catequese que propomos seguirá o Calendário Litúrgico iniciado na primeira semana do Advento e encerrado com a Solenidade de Nosso Senhor Jesus Cristo Rei do Universo. Os encontros estão intimamente ligados com o Ano Litúrgico; sendo assim é indispensável haver uma grande atenção com o Calendário Litúrgico em percurso. Deste modo, pode acontecer que alguns encontros devam ser antecipados e outros realizados posteriormente para estar em sintonia com o tempo que está sendo celebrado. Assim aproxima-se a catequese e a liturgia.</p> <p>A catequese que pensamos está estruturada em etapas, sendo quatro para a Primeira Eucaristia e três para a Crisma, permeada por várias celebrações. Cada Etapa terá a duração mínima de um ano. O tempo de cada etapa poderá ser alterado de acordo com a maturidade de cada catequizando.</p> <p>1ª Etapa</p> <p>A temática principal a ser trabalhada é o "querigma", fazendo com que os catequizandos conheçam e façam uma experiência mística de Jesus Cristo. Além de serem inseridos na dinâmica do calendário da Igreja – Ano Litúrgico – que se inicia no primeiro domingo do Advento e conclui-se com a Solenidade de Nosso Senhor Jesus Cristo Rei do Universo. Além de terem contato e aprenderem a manusear a Bíblia Sagrada, a recebendo em uma celebração na conclusão da primeira Etapa.</p> <p>2ª Etapa</p> <p>Cada encontro será refletido um trecho da "Profissão de Fé", onde os catequizandos terão uma noção geral da doutrina da Igreja e como vivê-la. No início da segunda Etapa os catequizandos receberão o Credo e, no final desta Etapa, numa celebração, professarão solenemente a fé.</p> <p>3ª Etapa</p> <p>Na terceira Etapa o catequizando irá refletir sobre a vida de oração, tendo como modelo a oração que o Senhor nos ensinou: O Pai-nosso. Em cada encontro será trabalhado uma petição da oração. No início da terceira Etapa os catequizandos receberão a oração do Pai-nosso impressa, e ao final da Etapa, numa celebração, a rezarão solenemente.</p> <p>4ª Etapa</p> <p>A quarta Etapa será um aprofundamento sobre os sete sacramentos e sacramentais. Nessa Etapa os catequizandos não batizados receberão o primeiro sacramento, e ao final da Etapa todos os catequizandos se aproximarão pela primeira vez do corpo e sangue de Cristo, participando da Eucaristia.</p> <p>Em relação à faixa etária dos catequizandos o material foi pensado e preparado de acordo com a pedagogia das idades, idealizado para todas as crianças que completarem 7 anos no ano de início da catequese. Ainda, nossa proposta quer possibilitar uma maior interação entre comunidade e família dos catequizandos, realizando-se um destaque, também, aos padrinhos de Batismo para resgatar o seu significado e importância de corresponsáveis por introduzir as crianças na fé cristã.</p> <p>Para cada Etapa preparamos para o catequizando um volume chamado Diário Catequético e Espiritual do Catequizando. Como o próprio nome revela, trata-se de um recurso no qual o catequizando fará o registro de algumas atividades de sua vivência de fé relacionada a cada encontro, como também tem-se espaços próprios para o registro das informações sobre cada domingo do Tempo Litúrgico em que ao catequizando é indicado o que registrar em relação a sua participação na celebração da Santa Missa.</p>', 2); -- material: Apresentação da Obra
delete from etapa_materiais where etapa_id=(select id from etapas where numero=2) and ordem=3; insert into etapa_materiais (etapa_id, titulo, conteudo_html, ordem) values ((select id from etapas where numero=2), 'Os Encontros e sua Organização', '<p>A nossa proposta para os encontros é para que as reflexões estejam estruturadas ao redor de duas mesas, a saber: a Mesa da Palavra e a Mesa da Partilha, buscando uma estreita ligação entre catequese e liturgia, em encontros dinâmicos e celebrativos.</p> <p>A Mesa da Palavra</p> <p>Consiste em organizar um ambão ou uma pequena mesa para colocar a Bíblia, ter uma vela acesa, usar toalha com a cor do Tempo Litúrgico que se está celebrando em um lugar de destaque e específico da sala de encontros que possibilite aos catequizandos aproximar-se ao seu redor. Com a inserção da Mesa da Palavra quer se dar destaque e valorizar a leitura da Bíblia, mostrando que não é apenas um livro a mais para ser estudado, como também orientar e fazer a experiência de acolhida da Palavra de um Deus que nos fala. O fato de mobilizar os catequizandos a ir até essa mesa, colocar-se de pé ao seu redor, trocar a toalha de acordo com o Tempo Litúrgico, solenizando a leitura bíblica, incentivando a sua escuta, possibilita revelar através dos gestos e posturas o valor e a importância que lhe damos em nossa comunidade Igreja. Além de remeter os catequizandos ao ambiente celebrativo da Eucaristia.</p> <p>A Mesa da Partilha</p> <p>Trata-se de uma grande mesa com várias cadeiras ao seu redor. É o local onde os catequizandos irão buscar compreender, com a ajuda do catequista, o sentido e significado da Palavra em seu contexto e para suas vidas. Ao redor da mesa, integrados, chegarão ao seu entendimento ao reconstruir o texto bíblico, dialogar, ouvir histórias, contemplar os símbolos presentes em cada encontro e nos textos bíblicos e, também, realizar diversas atividades. Nesta mesa, recordando o costume antigo das famílias de tomar a refeição, onde catequista e catequizandos saborearão o alimento da Palavra que dá vida e sacia toda sede.</p> <p>Os novos espaços destinados à catequese que propomos buscam, portanto, descaracterizar os lugares de encontro das salas de ensino escolar, mostrando que nossos catequistas não são professores, mas mistagogos que guiam os catequizandos para o Mistério, fazendo que tenham uma experiência viva e pessoal de Jesus Cristo. A cada encontro são oferecidas sugestões que deverão ser enriquecidas e adaptadas à realidade de cada comunidade. Num clima alegre e acolhedor a Palavra se atualiza e se transforma em oração e gestos concretos.</p>', 3); -- material: Os Encontros e sua Organização
delete from etapa_materiais where etapa_id=(select id from etapas where numero=2) and ordem=4; insert into etapa_materiais (etapa_id, titulo, conteudo_html, ordem) values ((select id from etapas where numero=2), 'Explicando Nossa Proposta', '<p>1. Estrutura dos Encontros – Subsídio do Catequista</p> <p>Na sequência apresentamos as orientações sobre a dinâmica de nossa proposta, para o catequista desenvolver os encontros, que consideramos necessárias para ajudar na sua ação catequética. Para tanto o Subsídio do Catequista propõe as orientações para cada encontro da seguinte forma:</p> <p><strong>Palavra inicial:</strong> Neste tópico o catequista encontrará os objetivos a serem atingidos com o encontro, ou a mensagem que deverá ser transmitida para cada catequizando.</p> <p><strong>Preparando o ambiente:</strong> Oferece sugestões de símbolos e maneiras de preparar e organizar os espaços; de materiais a serem providenciados para os encontros. Na preparação do ambiente é importante envolver os catequizandos distribuindo funções com antecedência, como por exemplo: um traz as flores, o outro acende a vela, um grupo prepara e ensaia os cantos. Poderá também ter uma imagem (de Jesus, Nossa Senhora ou do padroeiro da comunidade). Esta imagem poderá ser levada cada semana para a casa de um catequizando, que ficará responsável por trazer no próximo encontro. No dia em que a imagem estiver na casa, incentive-os a rezar em família.</p> <p><strong>Acolhida:</strong> Em todos os encontros é sugerida uma frase para acolhida dos catequizandos, com a intenção de prepará-los para a temática que será refletida no encontro.</p> <p><strong>Recordação da vida:</strong> Tem a intenção de recordar brevemente fatos e acontecimentos marcantes da comunidade e da sociedade. E ainda de recordar o tema e gesto concreto do encontro anterior. O catequista pode incentivar a leitura do que alguns catequizandos escreveram no Diário Catequético e Espiritual no decorrer da semana. Este momento poderá acontecer ao redor da Mesa da Palavra, como parte da oração inicial, ou a critério do catequista, na Mesa da Partilha, antes da oração.</p> <p>Na Mesa da Palavra: O momento em torno da Mesa da Palavra envolve:</p> <p><strong>Oração inicial:</strong> Traz sugestões de orações e propõe-se que o catequista, juntamente com os catequizandos, selecione cantos para a oração inicial. Este momento deverá ser dinamizado e ritualizado, pelos catequistas criativamente para envolver os catequizandos com a reflexão do tema, tornando este momento importante e especial, de tal modo que desperte nos catequizandos o desejo de participar ativamente dele.</p> <p><strong>Leitura do texto bíblico:</strong> Buscando resgatar a importância e dignidade da Palavra de Deus na vida do cristão, toda a temática dos encontros tem como tema gerador o texto bíblico proclamado. O texto bíblico é que norteia todo o encontro, fazendo com que os catequizandos sejam introduzidos na linguagem bíblica e atualizem a cada dia sua mensagem.</p> <p>Nesta segunda etapa, os catequizandos terão contato direto com a Bíblia, portanto o catequista poderá fazer uma escala e distribuir a cada encontro a passagem bíblica para o catequizando para que ele a proclame no próximo encontro. O catequizando sempre fará a primeira leitura do texto de maneira clara e ritual: fazendo uma saudação respeitosa antes e depois da leitura, beijando a Palavra quando for um evangelho mostrando a importância e dignidade de tal livro. Depois o catequista proclamará novamente o texto bíblico. Os textos deverão ser lidos ao menos duas vezes. A primeira leitura na íntegra pelo catequizando e a segunda pelo catequista de maneira pausada, com destaque para os versículos da temática do encontro. Seria importante que antes de cada encontro o catequista fizesse uma <em>lectio divina</em> (Leitura Orante da Bíblia procedendo: leitura, oração, meditação e contemplação). Durante os encontros de catequese, na medida do possível, utilizar do esquema da Leitura Orante da Bíblia com os catequizandos.</p> <p>Na Mesa da Partilha: É na Mesa da Partilha que o encontro se desenvolverá. Historinhas, dinâmicas e símbolos auxiliarão o catequista a transmitir a mensagem da Boa-Nova de Jesus Cristo. O catequista poderá adaptar, acrescentar ou até mesmo mudar as sugestões de acordo com a realidade de cada grupo. Por isso é indispensável que o catequista prepare com antecedência cada encontro. As historinhas são apresentadas em cada encontro, dando continuidade à dinâmica do material da primeira Etapa, só que desta vez tendo como personagens principais outras três crianças: Isabel, Leandro e Otávio, que viajam no tempo de Jesus, e atualizam a mensagem bíblica proposta no encontro. As histórias poderão ser contadas com fantoches, dedoches, cartazes, ou de outra maneira criativa. Os dedoches poderão ser confeccionados de acordo com cada história pelo catequista ou mesmo pelos catequizandos que poderão criá-los.</p> <p>Importante: Na segunda etapa, todos os catequizandos deverão levar para os encontros de catequese a Bíblia que receberam na celebração que marcou o término da primeira Etapa. Na "Mesa da Partilha", após a reconstrução do texto bíblico, o catequista poderá pedir aos catequizandos para que abram suas bíblias na passagem proclamada durante a oração inicial, para que façam uma leitura silenciosa e pessoal, onde poderão descobrir outros elementos além daqueles percebidos durante a "reconstrução" do texto bíblico, bem como aprimorar o manuseio da Bíblia.</p> <p><strong>Conclusão:</strong> Momento de comunicar aos catequizandos o compromisso da semana, o gesto concreto como maneira de atualizar na vivência de cada um a Palavra lida, meditada e contemplada. Também poderá recordar os aniversariantes de Batismo da semana e distribuir as funções para o próximo encontro.</p> <p><strong>Oração final:</strong> Realizar, de preferência, sempre ao redor da Mesa da Palavra ou de onde foi feita a oração inicial. O catequista incentiva os catequizandos a fazerem orações e preces espontâneas e pode concluir com a oração indicada para cada encontro, bem como pode realizar uma bênção.</p> <p><strong>Material de apoio:</strong> No material de apoio o catequista encontrará, em alguns encontros, textos, citações e sugestões de bibliografias para aprofundar a temática. Porém, é de suma importância que o catequista participe de encontros, cursos, reuniões e retiros para se atualizar e melhor se preparar.</p> <p>para esse tão importante ministério. Além do mais, será somente a partir disso que se poderá haver uma plena caminhada em sintonia com a diocese, paróquia e comunidade. Sugerimos, a partir de nossa experiência, que os catequistas da mesma etapa preparem juntos os seus encontros, seja em reuniões mensais, quinzenais ou semanais.</p> <p><strong>Lembretes:</strong> Ao final de alguns encontros o catequista encontrará alguns "lembretes", que o auxiliarão no desenvolvimento da catequese, de modo especial a fazer com que os encontros sejam vividos de acordo com a dinâmica do Ano Litúrgico.</p> <p>Celebrações: Em todas as etapas, sugerimos ao menos duas celebrações, com o intuito de reunir catequizandos, pais, padrinhos de Batismo e comunidade. As celebrações são contadas como encontros da catequese, e para garantir uma maior participação de todos, principalmente dos pais, sugere-se marcar dia e horário do encontro da celebração favorável a todos, optando para o dia da semana em que a comunidade costuma se reunir para o seu momento de oração e partilha. As celebrações deverão ser preparadas com antecedência, de preferência com a ajuda das pessoas da comunidade que já costumam se reunir semanalmente. Escolher quem presidirá, leitores, grupo de cantos, entre outros. É preciso comunicar previamente aos catequizandos e respectivas famílias do dia e horário da celebração. Os catequizandos de outras etapas poderão ser convidados a participar, bem como toda a paróquia, pastorais e movimentos.</p> <p>2. Na Catequese, a Organização das Atividades</p> <p>Cronograma: Na sequência propomos um modelo de cronograma para que o catequista possa registrar as principais informações que ocorrerão no decorrer do ano de catequese. O propomos por considerar que o planejamento é algo indispensável para o bom êxito de qualquer atividade; portanto, apresentamos um roteiro para organizar o cronograma das atividades a serem realizadas no decorrer da catequese para auxiliar nossos catequistas. É importante ressaltar que o mesmo poderá ser adaptado à realidade de cada comunidade. Um cronograma semelhante poderá ser preparado e entregue uma cópia aos catequizandos, para colar no Diário Espiritual do Catequizando, e outra às famílias dos catequizandos para que possam se organizar para participar das atividades da catequese.</p> <p>Cronograma das atividades da catequese Ano:</p> <p>[Espaço para preenchimento]</p> <ul> <li><p>Inscrições da catequese: <em>[Espaço para preenchimento]</em></p></li> <li><p>Período de visita às famílias dos catequizandos: <em>[Espaço para preenchimento]</em></p></li> <li><p>Celebração de apresentação e envio dos catequistas: <em>[Espaço para preenchimento]</em></p></li> <li><p>Início da catequese: <em>[Espaço para preenchimento]</em></p></li> <li><p>Encontro de preparação para a celebração de entrega do Símbolo – Com os pais e padrinhos de Batismo: <em>[Espaço para preenchimento]</em></p></li> <li><p>Celebração de entrega do Símbolo: <em>[Espaço para preenchimento]</em></p></li> <li><p>Celebração ecológica: <em>[Espaço para preenchimento]</em></p></li> <li><p>Período de recesso: <em>[Espaço para preenchimento]</em></p></li> <li><p>Quarta-feira de Cinzas: <em>[Espaço para preenchimento]</em></p></li> <li><p>Domingo de Ramos: <em>[Espaço para preenchimento]</em></p></li> <li><p>Missa dos Santos óleos: <em>[Espaço para preenchimento]</em></p></li> <li><p>Missa da Ceia do Senhor: <em>[Espaço para preenchimento]</em></p></li> <li><p>Vigília eucarística – Hora Santa: <em>[Espaço para preenchimento]</em></p></li> <li><p>Celebração da Paixão: <em>[Espaço para preenchimento]</em></p></li> <li><p>Sábado – Missa da vigília: <em>[Espaço para preenchimento]</em></p></li> <li><p>Celebração da Luz: <em>[Espaço para preenchimento]</em></p></li> <li><p>Domingo de Pentecostes: <em>[Espaço para preenchimento]</em></p></li> <li><p>Corpus Christi (enfeitar rua): <em>[Espaço para preenchimento]</em></p></li> <li><p>Missa de Corpus Christi: <em>[Espaço para preenchimento]</em></p></li> <li><p>Período de recesso: <em>[Espaço para preenchimento]</em></p></li> <li><p>Preparar celebração de recitação da "Profissão de Fé" com os pais e padrinhos de Batismo: <em>[Espaço para preenchimento]</em></p></li> <li><p>Celebração de recitação solene da "Profissão de Fé": <em>[Espaço para preenchimento]</em></p></li> <li><p>Reunião com os pais dos catequizandos (1ª): <em>[Espaço para preenchimento]</em></p></li> <li><p>Reunião com os pais dos catequizandos (2ª): <em>[Espaço para preenchimento]</em></p></li> <li><p>Reunião com os pais dos catequizandos (3ª): <em>[Espaço para preenchimento]</em></p></li> <li><p>Reunião com os pais dos catequizandos (4ª): <em>[Espaço para preenchimento]</em></p></li> <li><p>Outras datas: <em>[Espaço para preenchimento]</em></p></li> </ul> <p>Livro de registro dos catequizandos</p> <p>Na celebração de conclusão da primeira etapa, que chamamos de "Celebração de Inscrição do Nome e entrega do Livro" sugerimos que a comunidade tenha um livro que chamamos de "Livro de Registro dos Catequizandos", no qual poderá registrar o nome de todos os catequizandos, que concluíram a primeira etapa, dando o sentido de escolha, de eleição, além de ajudar a organização da catequese.</p> <p>A escolha do livro fica a critério de cada comunidade, podendo ser aqueles de capa preta que comumente se utiliza para redigir atas. Uma capa poderá ser confeccionada para valorizar o livro. Além dos nomes, outros dados poderão posteriormente ser registrados como no modelo abaixo:</p> <table> <colgroup> <col style="width: 20%"/> <col style="width: 20%"/> <col style="width: 20%"/> <col style="width: 20%"/> <col style="width: 20%"/> </colgroup> <tbody> <tr> <td style="text-align: center;"><strong>Nº</strong></td> <td style="text-align: center;"><strong>Catequizando</strong></td> <td style="text-align: center;"><strong>Data de Batismo</strong></td> <td style="text-align: center;"><strong>Data da Celebração de Inscrição do Nome</strong></td> <td style="text-align: center;"><strong>Data da 1ª Eucaristia</strong></td> </tr> <tr> <td style="text-align: center;">001</td> <td style="text-align: center;">Exemplo...</td> <td style="text-align: center;">15/07/1998</td> <td style="text-align: center;">00/11/2011</td> <td style="text-align: center;">20/11/2015</td> </tr> <tr> <td style="text-align: center;">002</td> <td style="text-align: center;">Exemplo...</td> <td style="text-align: center;">Não batizado</td> <td style="text-align: center;">00/11/2011</td> <td style="text-align: center;"><em>[Espaço para preenchimento]</em></td> </tr> <tr> <td style="text-align: center;">003</td> <td style="text-align: center;"><em>[Espaço para preenchimento]</em></td> <td style="text-align: center;"><em>[Espaço para preenchimento]</em></td> <td style="text-align: center;"><em>[Espaço para preenchimento]</em></td> <td style="text-align: center;"><em>[Espaço para preenchimento]</em></td> </tr> <tr> <td style="text-align: center;">004</td> <td style="text-align: center;"><em>[Espaço para preenchimento]</em></td> <td style="text-align: center;"><em>[Espaço para preenchimento]</em></td> <td style="text-align: center;"><em>[Espaço para preenchimento]</em></td> <td style="text-align: center;"><em>[Espaço para preenchimento]</em></td> </tr> </tbody> </table> <p>Assim, além do sentido espiritual de ter o nome inscrito, como eleito, escolhido, a catequese paroquial terá um controle de quantos catequizandos iniciaram no processo catequético e quantos chegaram ao término deste primeiro processo recebendo o Sacramento da Eucaristia. Um livro poderá ser suficiente para toda a paróquia, ou, se acharem necessário, cada comunidade poderá ter seu próprio livro.</p> <p>Sugestão para o termo de abertura do livro:</p> <p>Este livro, que contém ......... folhas, todas numeradas, a glória de Deus, destina-se ao solene registro dos nomes de todos os catequizandos assistidos pela Paróquia ............, com sede na cidade de ............, Diocese de ............, (Estado)....., que incorporados a Cristo buscam conhecer, aprofundar e vivenciar o Cristo. E para constar eu ............ (pároco) ............ assino e dou por aberto o presente livro de registro dos catequizandos.</p> <p>Aos ......... de ............ de .........</p>', 4); -- material: Explicando Nossa Proposta
delete from etapa_materiais where etapa_id=(select id from etapas where numero=2) and ordem=5; insert into etapa_materiais (etapa_id, titulo, conteudo_html, ordem) values ((select id from etapas where numero=2), 'Diário Catequético e Espiritual do Catequizando', '<p>O material do catequizando nesta primeira etapa será constituído apenas de um livro que intitulamos Diário Catequético e Espiritual do Catequizando, que, como o próprio nome sugere, será um diário onde o catequizando deverá ser incentivado a relatar sua vivência de fé. O Diário está dividido em duas partes:</p> <p>I Parte – Meus encontros de catequese</p> <p>Esta parte está organizada da seguinte forma:</p> <p>Meu momento de oração diária: Contém orientações para o catequizando realizar um momento diário de oração pessoal, que deve ser incentivado pelo catequista constantemente durante os encontros.</p> <p>Os encontros: Em cada encontro é proposto um pequeno texto fazendo menção ao tema a ser refletido, uma citação do texto bíblico acompanhado de uma ilustração. Ainda, propõe algumas perguntas e atividades para ajudar os catequizandos a fazer memória da experiência vivida no encontro, como também ajudá-los a meditar sobre a temática do encontro ou celebração. Propõe-se no Diário que os catequizandos escrevam seus pedidos e intenções de oração da semana. No final de cada encontro tem-se uma página chamada Espaço Complementar, com a finalidade de ser usada para registrar algumas atividades realizadas durante o encontro, como, por exemplo: colagens, transcrições de textos, bem como outras possibilidades que o catequista precisar criar para ajudar os catequizandos a melhor compreender cada tema. Por se tratar de um Diário, sua finalidade é ser um instrumento em que o catequizando possa contemplar suas experiências catequéticas e perceber o seu crescimento na fé.</p> <p>II Parte – Meu domingo</p> <p>Composta por um texto explicativo sobre o domingo e Ano Litúrgico, a segunda parte busca incentivar a participação dos catequizandos e seus familiares na Santa Missa. Para isso apresenta um roteiro para cada domingo, onde o catequizando deverá anotar as citações da Liturgia da Palavra, a cor litúrgica usada e uma breve mensagem sobre o que aprendeu ao participar da celebração.</p> <p>No Diário, ainda, o catequizando encontrará algumas orações básicas da vida do cristão. Sugere-se ao catequista orientá-los para que as rezem sozinhos ou com a família.</p>', 5); -- material: Diário Catequético e Espiritual do Catequizando
delete from etapa_materiais where etapa_id=(select id from etapas where numero=2) and ordem=6; insert into etapa_materiais (etapa_id, titulo, conteudo_html, ordem) values ((select id from etapas where numero=2), 'Como Aproveitar o Diário?', '<p>No primeiro dia de catequese, no final do encontro, o catequista deverá orientar os catequizandos de como utilizarem o Diário. E no decorrer dos encontros alertá-los para durante a semana realizarem os registros de sua catequese. As atividades do Diário em nossa experiência têm por intencionalidade serem realizadas em casa e, sempre que possível, junto com a família, não sendo necessário levá-lo em todos os encontros. Cabe ao catequista solicitar antecipadamente ao catequizando para trazê-lo ao encontro.</p> <p>O seu uso no encontro pode ser determinado pelo catequista para realizar:</p> <ul> <li><p>uma roda de conversa para partilha dos registros e experiências vividas ao término de um tempo litúrgico;</p></li> <li><p>produzir um debate sobre as mensagens litúrgicas;</p></li> <li><p>trabalhar com os catequizandos algumas questões específicas de cada tema, com o propósito de acompanhar o entendimento do conteúdo que os catequizandos estiverem registrando;</p></li> <li><p>uma análise que servirá de base para corrigir equívocos de entendimento;</p></li> <li><p>um encontro orante com as orações escritas pelos catequizandos... e muitas outras possibilidades.</p></li> </ul> <p>O Diário poderá substituir as "carteirinhas" ou "boletins" que existem em algumas comunidades onde o catequizando tem que levar na missa para assinar ou receber o carimbo para comprovar a presença nas celebrações.</p> <p>É importante que na primeira reunião com os pais, antes do início da catequese, o catequista os oriente para acompanhar os filhos e ajudá-los com o Diário Catequético e Espiritual do Catequizando, incentivando os filhos na oração diária e na participação da Celebração eucarística, como também nos registros sobre cada encontro.</p> <p>O nosso CAMINHO é Jesus Cristo, única razão dessa grande jornada.<br/> Bom trabalho a todos!<br/> <br/> Pe. Thiago e equipe</p>', 6); -- material: Como Aproveitar o Diário?
delete from etapa_materiais where etapa_id=(select id from etapas where numero=2) and ordem=7; insert into etapa_materiais (etapa_id, titulo, conteudo_html, ordem) values ((select id from etapas where numero=2), 'Subsídio para a Família', '<p>Visando contribuir oferecemos um subsídio para a família com um pequeno roteiro, para incentivar a criar uma rotina de oração, escolhendo um dia e horário da semana para se reunir e juntos rezarem. Neste subsídio apresentamos o roteiro para quatro encontros a serem realizados no decorrer das quatro semanas do Tempo do Advento. É apenas um "empurrãozinho" para que as famílias possam se organizar.</p> <p>Após este primeiro momento, o catequista, em sintonia com as atividades da diocese, da paróquia e de cada comunidade, poderá a cada mês indicar os subsídios já utilizados pelos mesmos nas reuniões de comunidade e de setor, como por exemplo: Leitura Orante da Bíblia, Campanha da Fraternidade, Novena de Pentecostes, mês vocacional, mês missionário, Novena de Natal, entre outros, incentivando as famílias a se reunirem e rezarem.</p> <p>Na primeira reunião com os pais e responsáveis pelos catequizandos, o catequista deverá orientá-los de como usufruir deste subsídio.</p> <p>O nosso CAMINHO é Jesus Cristo, única razão dessa grande jornada.<br/> Bom trabalho a todos!<br/> <br/> Pe. Thiago e Equipe</p>', 7); -- material: Subsídio para a Família
delete from etapa_materiais where etapa_id=(select id from etapas where numero=2) and ordem=8; insert into etapa_materiais (etapa_id, titulo, conteudo_html, ordem) values ((select id from etapas where numero=2), 'Ano Litúrgico', '<p>[Diagrama: Espiral do Ano Litúrgico – imagem não incluída no documento; conteúdo dos rótulos transcrito abaixo]</p> <p>2ª PARTE – TEMPO COMUM; Festa da Santíssima Trindade; Domingo de Pentecostes; Ascensão do Senhor; TEMPO PASCAL; PÁSCOA; 2º, 3º, 4º, 5º, 6º (semanas); Domingo de Páscoa; Sábado; Sexta-feira; Quinta-feira; SEMANA SANTA – TRÍDUO PASCAL; Quarta-feira de Cinzas; 1º, 2º, 3º, 4º (domingos da Quaresma); Domingo de Ramos; CICLO DA QUARESMA; TEMPO COMUM; 1ª PARTE; Cristo Rei; ADVENTO; CICLO DO NATAL; TEMPO DO NATAL; Natal do Senhor; Sagrada Família; Santa Mãe de Deus; Epifania; Batismo do Senhor; A (Alfa), Ω (Ômega).</p>', 8); -- material: Ano Litúrgico
delete from etapa_materiais where etapa_id=(select id from etapas where numero=2) and ordem=9; insert into etapa_materiais (etapa_id, titulo, conteudo_html, ordem) values ((select id from etapas where numero=2), 'Anexo 1.1 – O que é o "Ano Litúrgico"', '<p>Segundo A. Bergamini e tantos outros autores, o Ano Litúrgico não é uma ideia, um conceito antropológico ou uma simples explicação de uma maneira diferente de viver o ciclo de um ano; estas podem até constituir dimensões do mesmo, mas não defini-lo como tal. O Ano Litúrgico é uma pessoa: Jesus Cristo. O tempo da liturgia é o tempo de hoje onde se torna sagrada a presença de Deus nele, novamente se encarnando sob novas formas e dimensões e o tornando vivo e eficaz no meio da humanidade. O Ano Litúrgico é o mistério de Cristo celebrado e vivido na história da Igreja como "memória", "presença" e "profecia".</p> <p>O Ano Litúrgico é o mistério de Cristo na vida da Igreja como memória porque atualiza o evento salvador de Jesus no hoje do ser humano. Potencializa a humanidade para experimentar o acontecimento salvador no seu "hoje", relembrando o que Deus fez na história, o que faz no presente e gerando a expectativa boa de futuro.</p> <p>O Ano Litúrgico é o mistério de Cristo na vida da Igreja como presença de Jesus nos eventos cotidianos das pessoas. Gerando iluminação de fé aos crentes para relerem os fatos, acontecimentos, crises, dores, alegrias, vitórias, derrotas, conquistas e fracassos de cada um. Uma releitura positiva, pois o mistério presente não é derrotado, mas vitorioso e cheio de força: aquele da vida sobre a morte, da ressurreição sobre a cruz.</p> <p>O Ano Litúrgico é o mistério de Cristo na vida da Igreja como profecia, porque revela uma dimensão muito importante da Igreja, às vezes esquecida, de anunciar a Boa-Nova de Jesus, seu projeto de amor e de denunciar as forças contrárias a este projeto e tudo o que desvincula o ser humano de Deus e de sua proposta de vida. A profecia tem a função de desvelar realidades mortais para o ser humano e de mostrar que não se toma este caminho, pois o caminho a ser tomado é o da vida.</p> <p>Essas três dimensões do Ano Litúrgico, memória, presença e profecia do mistério de Cristo não podem ser vividas separadamente. Se assim acontecer perderá sua unidade e não manifestará sua base fundamental: a História da Salvação e a Unidade em Cristo de todo o plano de Deus.</p> <p>Pe. José Humberto Motta (Pe. Beto).</p> <p>MOTTA, J.H. O que é o "Ano Litúrgico". In: Cadernos de Liturgia da Arquidiocese de Ribeirão Preto. Ano I – Número 04 – Novembro/2008.</p>', 9); -- material: Anexo 1.1 – O que é o "Ano Litúrgico"
commit;
